                z=p[p['phase']==phase];R=np.column_stack([z['R_force_'+a] for a in 'xyz']);L=np.column_stack([z['L_force_'+a] for a in 'xyz']);mask=z['left_contacts']>0;right=R@e.ref['side'];left=L@e.ref['side'];phases.append(dict(name=s['name'],phase=phase,start_s=float(z['time_s'][0]),end_s=float(z['time_s'][-1]),right_contact_ratio=float(np.mean(z['right_contacts']>0)),left_contact_ratio=float(np.mean(mask)),right_vertical_mean_N=float(np.mean(R[:,2])),left_vertical_mean_N=float(np.mean(L[:,2])),left_normal_peak_N=float(np.max(z['left_normal_N'])),left_lateral_mean_at_contact_N=float(np.mean(left[mask])) if mask.any() else 0,right_lateral_mean_at_left_contact_N=float(np.mean(right[mask])) if mask.any() else 0,lateral_counterforce_fraction=float(np.mean(left[mask]*right[mask]<0)) if mask.any() else 0,net_contact_torque_rms_Nm=float(np.sqrt(np.mean(sum(z['net_torque_'+a]**2 for a in 'xyz')))),path_error_peak_mm=float(np.max(z['ball_path_error_mm']))))
