def write_report(summaries,phases,joints):
    chosen={s['name']:s for s in summaries};lines=['# M5-1 Bimanual reorientation and full upper-body coordination','', 'Single body_01 contact-only feasibility experiment. New files only; no PPO training. **The requested complete bimanual shooting reference is not physically validated.**','', '## 1. Error definitions','', 'The earlier 28–36 mm is Euclidean world wrist-origin IK residual: ||p_FK − (ball_initial − R_target @ old_rel0)|| × 1000. It uses the old local ball offset and a fixed world ball center; it is not physical servo error or ball drift. Fixed-wrist and half-orbit FK sequences can turn 150–180 degrees with <0.2 mm residual. That is geometric feasibility only.','', 'New metrics separate IK residual, intentional planned reposition, actual wrist servo error, and world ball path error. `right_local_change_mm` / `right_local_target_error_mm` remain legacy offset diagnostics and are not termination gates. Planned ball movement derives from wrist/grip geometry; it is a hypothesis, not observed free-throw truth.','', '## 2. Implementation and axes','', 'The new adapter uses actual MuJoCo FK/Jacobians, bounded shoulder/elbow/wrist IK, plus 9 trunk and 6 neck/head hinges. Left IK uses the same planned trunk as right IK rather than solving against a stale actual trunk. Final posture experiments constrain the full chest rotation toward a smoothly extended initial frame, with per-trunk-joint displacement bounded±0.4rad to suppress null-space twisting; they do not hold trunk joints at single fixed angles. Joint targets are filtered continuously at physics steps; no Euler branch decomposition. Whole-body target solving includes trunk-axis and wrist-extension components; head +Z aims toward the actual rim center.','', 'Wrist extension is a signed component of the elbow-relative wrist quaternion about the calibrated finger × palm-normal direction. It is a geometric model proxy, not measured clinical anatomy. Palm −Y is also a proxy for the capsule, not a scanned palm surface. `wrist_axis_calibration.csv` gives actual FK ±0.2rad perturbations and XML ranges. Forearm bone swing and body twist are separate; principal twist wraps at ±180°, so cumulative ball spin is recorded independently.','', '## 3. Physical A/B/C/D outcomes','', '| Condition | Duration s | Stop | Finger turn deg | Wrist component peak deg | Trunk straightening peak deg | Left rotation contact % | World path peak mm | Ball rise above initial mm |','|---|---:|---|---:|---:|---:|---:|---:|---:|']
    for name in NAMES:
        s=chosen[name];lines.append(f"| {name} | {s['duration_s']:.3f} | {s['reason']} | {s['max_finger_change_deg']:.2f} | {s.get('wrist_extension_peak_deg',0):.2f} | {s.get('trunk_extension_peak_deg',0):.2f} | {s['left_rotation_contact_ratio']*100:.2f} | {s['ball_world_path_peak_mm']:.2f} | {s['ball_rise_mm']:.2f} |")
    lines+=['','A is a preserved stable grip/lift control; its legacy readiness gate does **not** certify a natural bimanual shooting pose. Final B/C/D add the trunk posture safeguard. Earlier C_final/D_final failed before raising, with identical early paths; they remain in the results as pilots. A phase label C in B/C means post-turn holding, not ball raising. Actual raising is scheduled only in A/D and must be verified by measured ball height.','', '## 4. Right orientation, wrist and trunk','', 'The final posture-limited C can complete a large physical finger reorientation while preserving right holding; D adds overlapping raising and is judged separately on actual height and contact. This does not validate sustained guide support or shooting readiness. Shoulder/elbow translation and head alignment are measured in `derived_summaries.json`; target-versus-actual joint RMSE and limits are in `joint_comparison.csv`.','', 'Pure whole-body FK combines the requested 150° hand reorientation with wrist extension14.938° and trunk straightening8.003°, wrist position residual0.0276mm and orientation residual0.0965°. This has no contact dynamics and is not physical success; see whole_body_fk_screen.csv.\n\nThe pre-extension pilot `C_planned_fixed` physically reached about149.8° before later losing the ball; its geometric gate passed, bimanual/raising/readiness gates failed. This is a failed contact trial, not a successful shooting reference. The horizontal proximity pilot later achieved140° finger change, wrist component16.70° and trunk straightening7.30°, but its earlier unconstrained trunk null space allowed substantial twisting and it eventually lost contact at14.74s. D_horizontal_proximity stopped on200mm path error while still physically contacting both hands (right3, left1 points): this is tracking failure, not observed ball separation. Its ball rose87.32mm, not a successful full lift. Principal quaternion branch handling was checked explicitly; full-body FK screening is separate from actual holding. Geometric forearm twist approaches180° in some trials; XML limits alone do not establish clinical plausibility, and this remains a limitation. Adding extension is not automatically beneficial. Compare C_posture and C_posture_trunk_off, plus the earlier C_final, C_trunk_off, C_shallow_extension and D_small_extension; different stop times censor the final angles.','', '## 5. Left forces and stabilization','', 'Left contact must precede turning; a measured 0.25s weak-contact gate starts rotation. Force feedback changes only the hand target, not the ball. Raw contacts include geometry, normals, positions, forces and torque about ball center. In the earlier C_final/D_final rotation, left mean vertical force is −1.068N, left lateral force at contact −2.248N and right counterpart +2.009N. Actual left contacts are L_Ring3 and L_Thumb3 (normal Z weighted about−0.494 and−0.410). The lateral counterforce does not cancel the downward destabilization. Vertical fingers can touch the upper hemisphere and exert downward force even when the nominal palm target is lateral. Contact ratio alone is not evidence of useful support. `phase_force_balance.csv` records lateral counterforce and vertical force separately.','', 'Guide direction/clearance variants also tested horizontal and diagonal fingers. Some fail to obtain actual contact; closer placement can perturb the ball during approach. These were retained as independent physical failures.','', '## 6. Controller and limits','', 'Original PD+COM remains unchanged. Legacy wrist servo metrics replace only the selected arm target joints against actual upstream torso/root state; full_body_FK_tracking.csv additionally replaces every commanded hinge while retaining the actual free root. These are distinct errors, not equivalent to IK residual or ball drift. Saturation is recomputed against its body-scaled PD torque limits, not generic XML ctrlrange. Torque saturation uses the correct joint-name → PD-limit mapping; early A_final/B_final/C_final/D_final show0% in their recorded upper-body joints. Proximity pilots may saturate shoulder torque, so inspect joint_comparison.csv for final posture conditions. No target limit violations occurred in those early conditions. Earlier B_final arm-only right-wrist servo RMS is66.45mm versus IK residual0.054mm: target feasibility does not imply physical tracking. Earlier C_final right/left IK RMS is0.072/18.60mm and servo RMS14.86/10.90mm. No falls or MuJoCo warnings occurred in final A/B/C/D; both feet maintained contact. Positive COM margin does not imply hand contact stability. Root is free and never forced. Actual target errors/near-limit axes are recorded, not inferred from visual appearance.','', '## 7. Intentional movement versus escape','', 'The planned hand/ball reposition relaxes the old fixed offset assumption and may move the planned ball sideways by roughly0.2m. Such a path is not yet validated as natural basketball motion. World ball-versus-planned-path >0.2m is a tracking-error stop and must not automatically be called actual ball separation. Actual loss requires absent hand contacts and relative geometry evidence. Additional stops include sustained absence of both-hand force contacts, low ball height, overload, fall or warnings. The path threshold is a stop limit, not a success tolerance; bimanual success also requires <80mm path error and sustained useful contact.','', '## 8. GUI/GIF and diagnostic probe','', 'GIF/replay displays saved physical states only; it does not demonstrate continued holding after termination. Ended conditions freeze and are labeled. Arrow origins are shifted20cm upward for visibility; directions remain actual FK vectors. Green arrows show finger direction, blue palm normal. Geometric feasibility and physical validity stay distinct. Small extension/flexion probe is a readiness diagnostic, never a physical release success; early-aborted conditions do not run it. C runs a diagnostic after its turn; this does not override its failed bimanual/readiness gates. In A only, mean rim-directed ball velocity changes from−0.00015m/s (9.8–10.0s) to+0.02539m/s (after10.6s), with peak+0.03293m/s. This does not validate a shooting-ready posture or release in B/C/D.','', '## 9. Reference and future curriculum','', 'Each trial stores target_qpos NPZ + physical states + CSV. `m5_bimanual_reference.py` returns interpolated humanoid targets with root quaternion SLERP, without setting physics state. These NPZ files are body-specific MuJoCo coordinates, **not SMPL+H axis-angle motion**. Failed references have physical_reference_valid=false. Curriculum records independent orientation/extension/guide/trunk/raising/readiness gates.','', 'Future small residual experiments can start at the protected stable right holding state and learn weak lateral guide approach before rotation. They need not wait for a perfect reference, but must terminate on physical escape/fall and compare against a no-learning baseline. No PPO has been run here.','', '## 10. Files, commands and protection','', 'Regression:136 unique tests passed. SHA256:2416 protected files unchanged. GUI saved-state replay smoke test opened and closed successfully with mjpython on macOS.\n\nNew code: examples/m5_bimanual_reorientation.py, m5_bimanual_body_ik.py, m5_bimanual_reference.py, m5_bimanual_reorientation_report.py, tests/test_m5_bimanual_reorientation.py. Output: outputs/m5_1_bimanual_reorientation/. Existing scientific assets are verified against preservation_before.json; see preservation_audit.json and regression_tests.log. No Git commands were used.','', 'Run from team mujoco/SMPLSim:', '```bash','PYTHONDONTWRITEBYTECODE=1 ../../../basketball-r1/.venv/bin/mjpython examples/m5_bimanual_reorientation.py --name D_gui_01 --condition D --yaw -150 --orbit 0 --support-tilt 0 --guide-force .6 --finger-flex 0 --clearance .015 --guide-finger-elevation 0 --proximity-guide --trunk-extension 8 --wrist-extension 15 --gui --speed 2','PYTHONDONTWRITEBYTECODE=1 ../../../basketball-r1/.venv/bin/mjpython examples/m5_bimanual_reorientation_report.py --replay C_coupled --speed 2','```','Each physical run name must be new to preserve previous results. Replay is explicitly labeled saved-state replay. Speed controls wall-time throttling; it cannot accelerate computation beyond the solver/IK cost.']
    c=chosen['C_coupled'];d=chosen['D_coupled'];lines+=['', '## Final quantitative details', '', f"C: rotation{c['max_finger_change_deg']:.2f}°, wrist component{c['wrist_extension_peak_deg']:.2f}°, trunk extension{c['trunk_extension_peak_deg']:.2f}°, local ball drift{c['ball_local_change_peak_mm']:.2f}mm. Right force-contact duty{c['right_contact_ratio']*100:.2f}% (brief contact gaps are not a drop), left rotation duty{c['left_rotation_contact_ratio']*100:.2f}%, left load peak{c['left_force_peak_N']:.3f}N. Head late error{c['head_error_late_mean_deg']:.2f}°, COM minimum{c['min_com_margin_mm']:.2f}mm, feet100%. Shoulder/elbow displacement peaks{c['R_shoulder_translation_peak_mm']:.2f}/{c['R_elbow_translation_peak_mm']:.2f}mm.", '', f"C right/left IK RMS{c['R_ik_position_rms_mm']:.2f}/{c['L_ik_position_rms_mm']:.2f}mm; arm-only commanded FK servo RMS{c['R_wrist_servo_rms_mm']:.2f}/{c['L_wrist_servo_rms_mm']:.2f}mm; full-body commanded FK RMS{c['R_full_body_target_FK_rms_mm']:.2f}/{c['L_full_body_target_FK_rms_mm']:.2f}mm. These substantial tracking residuals are unresolved even though angular reorientation and physical right holding occur. Final elbow operational extension reserve{c['final_elbow_extension_reserve_deg']:.2f}° and wrist rim-directed reserve{c['final_wrist_rim_rotation_reserve_rad']:.3f}rad are FK diagnostics, not clinical ROM or verified shooting ability.", '', f"D stopped at{d['duration_s']:.3f}s with right/left contact counts{d['final_right_contacts']}/{d['final_left_contacts']}; observed separation={d['observed_separation_at_stop']}. Initial-height and raising-segment measurements differ: raising-segment ball/wrist maximum increases{d.get('raising_segment_ball_rise_mm',0):.2f}/{d.get('raising_segment_wrist_rise_mm',0):.2f}mm. The intended full rise and shooting readiness were not reached.", '', 'Trunk controls: C_posture_trunk_off stops7.22s with local drift271.82mm, whereas C_posture completes14.87s with26.05mm drift; C_coupled further reduces drift to11.66mm. B_matched_trunk turns153.79° but loses holding8.49s without guide. Different preparation gate times (B3.00s versus C3.64s) and deterministic single trials limit causal attribution; no success-rate claim is made.']
    (OUT/'M5_1_BIMANUAL_COORDINATION_SUMMARY.md').write_text('\n'.join(lines)+'\n')

def arrows(scene,m,d):
    for side in ('R','L'):
        w=m.body(side+'_Wrist').id;p=d.xpos[w];W=d.xmat[w].reshape(3,3);finger=d.xpos[m.body(side+'_Middle1').id]-p;finger/=max(np.linalg.norm(finger),1e-12)
        for direction,color in [(finger,[.1,1,.1,1]),(-W[:,1],[.1,.5,1,1])]:
            if scene.ngeom>=scene.maxgeom:return
            p_arrow=p+np.array([0.,0.,.20]);g=scene.geoms[scene.ngeom];mujoco.mjv_initGeom(g,mujoco.mjtGeom.mjGEOM_ARROW,np.zeros(3),np.zeros(3),np.eye(3).ravel(),np.array(color,dtype=np.float32));mujoco.mjv_connector(g,mujoco.mjtGeom.mjGEOM_ARROW,.006,p_arrow,p_arrow+.15*direction);scene.ngeom+=1

def camera():
    cam=mujoco.MjvCamera();cam.lookat[:]=[.25,0,1.3];cam.distance=2.5;cam.azimuth=110;cam.elevation=-10;return cam

def gif(names):
    import imageio.v2 as imageio
    from PIL import Image,ImageDraw
    m=mujoco.MjModel.from_xml_path(str(MODEL));d=mujoco.MjData(m);renderer=mujoco.Renderer(m,420,420);cam=camera();states=[np.load(OUT/n/'states.npz') for n in names];summaries=[json.loads((OUT/n/'summary.json').read_text()) for n in names];frames=[]
    try:
        for t in np.arange(0,max(s['time_s'][-1] for s in states)+.05,.1):
            imgs=[]
            for n,s,z in zip(names,states,summaries):
                i=int(np.argmin(abs(s['time_s']-t)));d.qpos[:]=s['qpos'][i];mujoco.mj_forward(m,d);renderer.update_scene(d,camera=cam);arrows(renderer.scene,m,d);im=Image.fromarray(renderer.render().copy());draw=ImageDraw.Draw(im);draw.text((8,8),f'{n}  {s["time_s"][i]:.2f}s',fill='white');draw.text((8,26),'PHYSICS REPLAY / green=finger blue=palm',fill='white')
                if t>s['time_s'][-1]:draw.text((8,45),'ENDED: '+z['reason'],fill='orange')
                imgs.append(np.asarray(im))
            frames.append(np.concatenate(imgs,axis=1))
        imageio.mimsave(OUT/('comparison_'+'_'.join(names)+'.gif'),frames,duration=100,loop=0);Image.fromarray(frames[min(50,len(frames)-1)]).save(OUT/('comparison_'+'_'.join(names)+'.png'))
    finally:renderer.close()

def replay(name,speed,seconds=None):
    import mujoco.viewer
    if not np.isfinite(speed) or speed<=0:raise ValueError('Replay speed must be >0')
